{
  "capability": "returns-reverse-logistics",
  "version": "1.0.0",
  "scenarios": [
    {
      "id": "RRL-001",
      "name": "Standard electronics return within window with all accessories",
      "difficulty": "easy",
      "category": "return-authorisation",
      "context": {
        "situation": "A customer purchased a pair of Sony WH-1000XM5 wireless headphones ($349.99) 12 days ago from your e-commerce site. They want to return them because 'the noise cancellation didn't meet my expectations.' The customer's account shows 2 years of history, $4,200 lifetime spend, and a 12% return rate. The return request was submitted through the online portal with reason 'not as expected.' The headphones are within the 30-day return window for electronics.",
        "available_data": {
          "customer_name": "Marcus Thompson",
          "order_number": "ORD-2025-77412",
          "product": "Sony WH-1000XM5 Wireless Headphones",
          "product_sku": "SNY-WH1000XM5-BLK",
          "purchase_price_usd": 349.99,
          "purchase_date": "2025-06-03",
          "return_request_date": "2025-06-15",
          "return_window_end": "2025-07-03",
          "return_reason": "Not as expected",
          "customer_ltv_usd": 4200,
          "customer_return_rate_pct": 12,
          "customer_account_age_years": 2,
          "product_category": "electronics",
          "restocking_fee_policy": "15% for opened electronics"
        }
      },
      "task": "Process this return request: determine if RMA should be approved, identify what restocking fee (if any) applies, outline the inspection steps upon receipt, and determine the likely disposition of the returned product.",
      "evaluation_criteria": [
        {
          "criterion": "rma_approval",
          "weight": 0.25,
          "rubric": {
            "pass": "Approves the RMA without hesitation — the return is within the 30-day window, the customer is in good standing, and the return reason is valid. Generates RMA number, provides return shipping instructions, and communicates the expected refund timeline. No fraud indicators present (12% return rate is well within normal).",
            "fail": "Hesitates on approval, questions the customer's reason, or flags for fraud review despite no indicators. Alternatively, approves but fails to provide clear return instructions or timeline."
          }
        },
        {
          "criterion": "restocking_fee",
          "weight": 0.25,
          "rubric": {
            "pass": "Correctly identifies that a 15% restocking fee ($52.50) applies for opened electronics. Communicates this to the customer upfront before processing — the customer should know the net refund will be $297.49. Notes that if the product turns out to be defective (noise cancellation hardware issue), the fee would be waived.",
            "fail": "Waives the restocking fee without justification (the product isn't defective). Alternatively, applies the fee but doesn't communicate it to the customer before processing, or doesn't note the defective-product waiver."
          }
        },
        {
          "criterion": "inspection_plan",
          "weight": 0.25,
          "rubric": {
            "pass": "Outlines the inspection upon receipt: (1) verify serial number matches the sold unit, (2) visual inspection for cosmetic damage, (3) functional test — power on, Bluetooth pairing, active noise cancellation test, (4) check ear pads for wear/hygiene, (5) confirm all accessories present (cable, case, adapter). Notes that ear pads should be replaced before resale ($8-12 cost) as a hygiene measure.",
            "fail": "Generic 'inspect the product' without specifying what to check. Does not mention serial number verification (the key swap-fraud check). Does not mention the ear pad hygiene consideration."
          }
        },
        {
          "criterion": "disposition_routing",
          "weight": 0.25,
          "rubric": {
            "pass": "If the headphones pass inspection and grade as A/B: route to 'open box' resale at 70-80% of retail ($245-280) after replacing ear pads. If functional test reveals a genuine noise cancellation defect: waive restocking fee, refund in full, route to vendor RTV or refurbishment. Knows that premium headphones in Grade B condition have strong open-box demand.",
            "fail": "Does not consider disposition at all — focuses only on the refund. Suggests restocking as new (cannot — they were opened and used). Does not differentiate the disposition path based on whether a defect is found."
          }
        }
      ]
    },
    {
      "id": "RRL-002",
      "name": "Simple apparel return with tags still attached",
      "difficulty": "easy",
      "category": "return-authorisation",
      "context": {
        "situation": "A customer wants to return a women's winter jacket (Canada Goose Expedition Parka, $1,295.00) purchased 8 days ago. Return reason: 'ordered wrong size.' All original tags are attached, the jacket is in its original garment bag, and the customer has the receipt. The customer wants to exchange for a different size but the desired size is out of stock. They're asking for a full refund instead.",
        "available_data": {
          "customer_name": "Jennifer Walsh",
          "order_number": "ORD-2025-81203",
          "product": "Canada Goose Expedition Parka - Red - Size M",
          "product_sku": "CG-EXP-RED-M",
          "purchase_price_usd": 1295.00,
          "purchase_date": "2025-11-18",
          "return_request_date": "2025-11-26",
          "return_window_end": "2025-12-18",
          "return_reason": "Wrong size — exchange requested but desired size unavailable",
          "tags_attached": true,
          "original_packaging": true,
          "customer_ltv_usd": 6800,
          "product_category": "premium apparel"
        }
      },
      "task": "Process this return: approve or deny, determine the refund amount, outline the inspection process, and route the disposition.",
      "evaluation_criteria": [
        {
          "criterion": "return_processing",
          "weight": 0.30,
          "rubric": {
            "pass": "Approves full refund of $1,295.00 — tags attached, original packaging, within window, no restocking fee for apparel returns. Processes as refund to original payment method since the desired exchange size is unavailable. Notes the customer originally wanted an exchange and offers to notify when the desired size comes back in stock.",
            "fail": "Applies a restocking fee to a tags-attached apparel return. Does not offer to notify about size availability. Processes as store credit when the customer requested a refund."
          }
        },
        {
          "criterion": "inspection_and_grading",
          "weight": 0.35,
          "rubric": {
            "pass": "Grade A — tags attached, original packaging. Inspection checklist: verify tags are genuine Canada Goose tags (luxury authentication), check for odour (perfume, smoke), UV light check for cosmetic traces, verify fur ruff condition (common damage point on CG parkas), check zipper function. Notes that Canada Goose is a high-counterfeit-risk brand and authentication matters.",
            "fail": "Does not mention authentication for a premium/luxury brand. Does not check for odour or cosmetic traces despite tags being attached (tags can be reattached). Grades without any inspection — assumes Grade A based solely on customer's description."
          }
        },
        {
          "criterion": "disposition",
          "weight": 0.35,
          "rubric": {
            "pass": "Restock as new — tags attached, authenticated, no signs of wear. This is a $1,295 premium item with full margin recovery. Notes that winter apparel returned in November (still in season) has maximum restock value. If it were returned in March, the seasonal carrying cost calculation would change.",
            "fail": "Routes to open-box or liquidation when the item is in perfect restockable condition. Does not consider the seasonal timing factor for winter apparel."
          }
        }
      ]
    },
    {
      "id": "RRL-003",
      "name": "No-receipt return of moderate-value item",
      "difficulty": "easy",
      "category": "return-authorisation",
      "context": {
        "situation": "A customer walks into your retail store with a KitchenAid Stand Mixer (current retail $429.99) and no receipt. They claim it was a birthday gift received 3 weeks ago. The mixer is in opened but apparently unused condition — the bowl still has the protective film, and the attachment hub has no food residue. The customer wants a cash refund. Your POS system cannot locate a matching transaction under the customer's name, phone number, or any payment method they provide.",
        "available_data": {
          "product": "KitchenAid Artisan Stand Mixer - Empire Red",
          "product_sku": "KA-ART-5QT-RED",
          "current_retail_price_usd": 429.99,
          "lowest_recent_selling_price_usd": 349.99,
          "receipt_available": false,
          "transaction_lookup_result": "No matching transaction found",
          "product_condition": "Opened, appears unused, all accessories present",
          "customer_request": "Cash refund",
          "no_receipt_return_policy": "Store credit at lowest recent selling price, max $75 per transaction, 3 per rolling 12 months, ID required",
          "customer_id_provided": true
        }
      },
      "task": "Determine how to handle this no-receipt return: what refund type and amount, what the fraud considerations are, and how to communicate the decision to the customer.",
      "evaluation_criteria": [
        {
          "criterion": "policy_application",
          "weight": 0.35,
          "rubric": {
            "pass": "Applies no-receipt return policy correctly: store credit (not cash) at the lowest recent selling price ($349.99, not current retail of $429.99). However, notes that the $349.99 exceeds the $75 per-transaction cap for no-receipt returns. This means the return cannot be processed under standard no-receipt policy. Offers alternatives: customer can provide gift-giver's info for receipt lookup, or contact customer service with gift-giver's order details.",
            "fail": "Issues a cash refund at current retail price ($429.99) — violates no-receipt policy on both refund type and amount. Alternatively, issues store credit at $429.99 (wrong price) or at $349.99 without noting the $75 cap issue."
          }
        },
        {
          "criterion": "fraud_awareness",
          "weight": 0.30,
          "rubric": {
            "pass": "Recognises the fraud risk: no-receipt returns of high-value items are a primary receipt fraud vector (returning shoplifted merchandise for credit). Records the customer's ID as required. Notes that KitchenAid mixers are a commonly shoplifted small appliance. Does not accuse the customer — the birthday gift story is plausible — but follows the no-receipt protocol exactly because it exists to manage this risk.",
            "fail": "Processes the return without recording ID. Does not recognise the fraud risk. Alternatively, accuses the customer of theft or refuses the return entirely without offering alternatives."
          }
        },
        {
          "criterion": "customer_communication",
          "weight": 0.35,
          "rubric": {
            "pass": "Explains the no-receipt policy clearly and empathetically: 'Without a receipt or transaction match, we can offer store credit at the lowest recent price, but this item exceeds our per-transaction limit for no-receipt returns. If the person who gave you the gift can provide the receipt or their payment method, we can process a full refund. Alternatively, I can help you contact our customer service team to locate the original transaction.' Offers multiple paths forward.",
            "fail": "Bluntly refuses with no alternatives. Says 'we can't do anything without a receipt.' Does not offer to help locate the transaction through the gift-giver. Makes the customer feel suspected of wrongdoing."
          }
        }
      ]
    },
    {
      "id": "RRL-004",
      "name": "Straightforward defective product return with vendor RTV opportunity",
      "difficulty": "easy",
      "category": "vendor-recovery",
      "context": {
        "situation": "A customer returns a robot vacuum (iRobot Roomba j7+, $599.99) purchased 22 days ago. The customer reports that the vacuum's mapping function fails consistently — it cannot complete a mapping run without getting stuck in a loop. You've received 14 returns of this specific SKU in the past 60 days, all citing navigation or mapping issues. Your total sales of this SKU in the same period are 340 units. The vendor (iRobot) has a standard RTV agreement with a 90-day claim window and a 2% baseline defect threshold. Your RTV minimum shipment value is $300.",
        "available_data": {
          "product": "iRobot Roomba j7+ Robot Vacuum",
          "product_sku": "IRBT-J7PLUS-BLK",
          "purchase_price_usd": 599.99,
          "wholesale_cost_usd": 385.00,
          "return_count_60_days": 14,
          "units_sold_60_days": 340,
          "defect_rate_pct": 4.12,
          "vendor": "iRobot",
          "vendor_rtv_window_days": 90,
          "vendor_defect_threshold_pct": 2.0,
          "rtv_minimum_shipment_value_usd": 300,
          "customer_return_reason": "Mapping function failure — vacuum gets stuck in loop",
          "days_since_purchase": 22,
          "return_window_days": 30
        }
      },
      "task": "Process the customer's return, determine the vendor recovery approach for this individual unit and the broader defect pattern, and outline next steps for the SKU.",
      "evaluation_criteria": [
        {
          "criterion": "customer_return_processing",
          "weight": 0.25,
          "rubric": {
            "pass": "Full refund, no restocking fee — the product is defective. Process immediately. Offer the customer a replacement if they want one (the defect may be unit-specific, not SKU-wide), or suggest an alternative model. Do not make the customer wait for the vendor claim to be resolved.",
            "fail": "Applies restocking fee to a defective return. Makes the customer wait for vendor resolution before issuing refund. Does not offer a replacement or alternative."
          }
        },
        {
          "criterion": "individual_unit_rtv",
          "weight": 0.25,
          "rubric": {
            "pass": "Route this unit to the RTV staging area. The unit's wholesale cost ($385) exceeds the $300 minimum shipment threshold, so it could be shipped individually, but batching with other defective units is more efficient. Document the defect (customer report + functional test confirming mapping failure) for the RTV claim. The 90-day RTV window gives ample time to batch.",
            "fail": "Does not identify this as an RTV-eligible unit. Disposes of the defective unit without pursuing vendor recovery. Does not mention documentation requirements for the RTV claim."
          }
        },
        {
          "criterion": "defect_pattern_response",
          "weight": 0.30,
          "rubric": {
            "pass": "The 4.12% defect rate exceeds the 2% vendor threshold — this triggers a formal quality complaint to iRobot. Calculates excess returns: 14 returns - (340 × 2% = 6.8 baseline) = ~7 excess defective units attributable to the vendor. Files a formal defect claim covering the excess units. Requests root cause analysis from iRobot. Considers whether to continue selling the SKU while the vendor investigates (4.12% is concerning but not yet at the 8% stop-sale threshold).",
            "fail": "Does not recognise the defect rate pattern. Treats each return as an individual case without aggregating. Does not file a formal defect claim. Does not calculate the excess returns above baseline."
          }
        },
        {
          "criterion": "sku_management",
          "weight": 0.20,
          "rubric": {
            "pass": "Continue selling but monitor weekly. At 4.12%, the defect rate is above the 2% alert threshold but below the 8% stop-sale threshold. Alert vendor management team. Request corrective action plan from iRobot within 14 days. If defect rate continues climbing toward 8%, prepare to pull from active sales. Check if a firmware update from iRobot addresses the mapping issue — robot vacuum mapping problems are often software-fixable.",
            "fail": "Either ignores the defect rate entirely or overreacts by pulling the SKU from sale at 4.12% without following the threshold framework. Does not consider the firmware update possibility."
          }
        }
      ]
    },
    {
      "id": "RRL-005",
      "name": "Gift receipt return during post-holiday markdown period",
      "difficulty": "easy",
      "category": "policy-exceptions",
      "context": {
        "situation": "It is January 15. A customer presents a gift receipt for a Ninja Foodi Pressure Cooker. The gift receipt shows it was purchased on December 2 for $179.99 (at regular price). The product is currently on post-holiday clearance for $129.99 (28% markdown). The item is sealed in original packaging, clearly never opened. The customer wants store credit — they already have a pressure cooker and want to use the credit toward something else.",
        "available_data": {
          "product": "Ninja Foodi 8-Qt Pressure Cooker",
          "product_sku": "NJ-FOODI-8QT",
          "gift_receipt_purchase_price_usd": 179.99,
          "current_selling_price_usd": 129.99,
          "purchase_date": "2025-12-02",
          "return_date": "2026-01-15",
          "extended_holiday_return_window": "Purchases Nov 1 - Dec 31 returnable through Jan 31",
          "product_condition": "Sealed, original packaging, never opened",
          "customer_request": "Store credit",
          "gift_receipt": true
        }
      },
      "task": "Determine the correct refund amount and type for this gift receipt return, considering the price discrepancy between purchase and current selling price.",
      "evaluation_criteria": [
        {
          "criterion": "refund_calculation",
          "weight": 0.40,
          "rubric": {
            "pass": "Issues store credit at the purchase price ($179.99) — the gift receipt documents what was paid, and the store credit should reflect the gift-giver's expenditure. The current markdown to $129.99 is irrelevant; the gift receipt establishes the value. Notes that the holiday return window covers this return (Dec 2 purchase, Jan 15 return, within the Jan 31 extended window).",
            "fail": "Issues credit at the current clearance price ($129.99) — this short-changes the customer by $50 relative to what was paid. Alternatively, issues a cash refund instead of store credit (gift receipts get store credit, not cash)."
          }
        },
        {
          "criterion": "arbitrage_awareness",
          "weight": 0.30,
          "rubric": {
            "pass": "Recognises that this is the opposite of the typical gift-receipt arbitrage scenario. Normally, the risk is the customer returning during a markdown to profit from the higher purchase price. In this case, the customer is legitimately returning a gift for store credit — the $179.99 credit reflects what the gift-giver paid and is correct. Notes that if a pattern of gift-receipt returns emerges during markdown season (many different customers, same products), that would be an arbitrage signal. This individual case is not suspicious.",
            "fail": "Does not recognise the gift-receipt price-discrepancy issue at all. Alternatively, flags this as fraud or arbitrage when it's a straightforward gift return."
          }
        },
        {
          "criterion": "disposition",
          "weight": 0.30,
          "rubric": {
            "pass": "Restock immediately. The item is sealed and unopened — Grade A. However, the item is currently on clearance at $129.99, so the restock recovers $129.99 against the $179.99 credit issued. The net cost of this return is $50 (the markdown gap). This is a normal cost of holiday return processing. Notes that restocking clearance items quickly is important before the price drops further.",
            "fail": "Does not consider the financial impact of the markdown gap on the return cost. Routes a sealed, unopened item to liquidation instead of restocking."
          }
        }
      ]
    },
    {
      "id": "RRL-006",
      "name": "Opened cosmetics return — regulatory constraint",
      "difficulty": "easy",
      "category": "inspection-grading",
      "context": {
        "situation": "A customer wants to return an opened Lancôme Teint Idole Ultra 24H Foundation ($47.00) purchased 5 days ago. The customer says the shade doesn't match their skin tone despite using the in-store colour match tool. The bottle has been opened, approximately 20% of the product has been used (customer tested it over several days), and the pump dispenser has visible product residue. The customer is a loyalty programme member with $8,500 in annual purchases.",
        "available_data": {
          "product": "Lancôme Teint Idole Ultra 24H Foundation - 320N",
          "product_sku": "LCM-TIDU-320N",
          "purchase_price_usd": 47.00,
          "purchase_date": "2025-03-10",
          "return_date": "2025-03-15",
          "product_condition": "Opened, approximately 20% used",
          "return_reason": "Wrong shade — doesn't match skin tone",
          "customer_ltv_annual_usd": 8500,
          "loyalty_tier": "Gold",
          "return_window_days": 30,
          "product_category": "cosmetics"
        }
      },
      "task": "Process this return: determine acceptance, refund, and disposition, considering both the regulatory constraints on opened cosmetics and the customer relationship.",
      "evaluation_criteria": [
        {
          "criterion": "return_acceptance_and_refund",
          "weight": 0.35,
          "rubric": {
            "pass": "Accept the return and issue a full refund. Cosmetics shade-matching issues are a known, expected return reason and most retailers accept opened cosmetics returns within the window despite the product being used. No restocking fee — this is not the customer's fault (the colour match tool failed). The customer's $8,500 annual spend further supports full accommodation. Process to original payment method.",
            "fail": "Denies the return because the product was opened/used. While the regulatory constraint prevents restocking, the policy still allows the return. Penalising the customer for using a product to test shade match would be hostile to the category's business model."
          }
        },
        {
          "criterion": "disposition",
          "weight": 0.35,
          "rubric": {
            "pass": "DESTROY. Opened cosmetics cannot be restocked, resold, donated, or liquidated regardless of how much product remains. This is a regulatory requirement — FDA considers opened cosmetics adulterated once the seal is broken and the product contacts skin. The $47.00 is a total write-off on the disposition side. No vendor recovery — shade mismatch is not a defect.",
            "fail": "Suggests restocking the opened cosmetics. Routes to liquidation or donation. Attempts to resell as 'tester' (testers are manufacturer-provided, not repurposed returns). Does not recognise the regulatory constraint."
          }
        },
        {
          "criterion": "systemic_response",
          "weight": 0.30,
          "rubric": {
            "pass": "Notes the colour-match tool failure and recommends feedback to the cosmetics department: if shade 320N is generating returns for colour mismatch, either the tool's calibration or the shade's description/swatch may be inaccurate. Checks return data for this specific shade — if 320N has a higher-than-average return rate, it's a product listing issue, not a customer issue. The $47 per-return write-off multiplied across many customers is significant if it's a systemic shade-matching problem.",
            "fail": "Treats this as a one-off event without considering whether the shade mismatch indicates a broader product or tooling issue. Does not think about the systemic cost of cosmetics returns."
          }
        }
      ]
    },
    {
      "id": "RRL-007",
      "name": "Cross-channel return with online flash-sale price discrepancy",
      "difficulty": "medium",
      "category": "cross-channel",
      "context": {
        "situation": "A customer purchased a Dyson V15 Detect vacuum online during a 4-hour flash sale for $499.99 (regular online price $649.99, regular store price $699.99). The customer now wants to return it in-store. The store associate scans the barcode and the POS shows the current store price of $699.99. The customer's order confirmation email on their phone shows $499.99. The store's return system does not have direct access to the online order management system — the associate must manually look up online orders through a separate portal.",
        "available_data": {
          "product": "Dyson V15 Detect Cordless Vacuum",
          "product_sku": "DYS-V15-DET",
          "online_flash_sale_price_usd": 499.99,
          "regular_online_price_usd": 649.99,
          "current_store_price_usd": 699.99,
          "order_number": "ORD-2025-92104",
          "purchase_date": "2025-04-08",
          "return_date": "2025-04-20",
          "purchase_channel": "Online (flash sale)",
          "return_channel": "In-store",
          "return_window_days": 30,
          "store_pos_online_access": "Separate portal, manual lookup required",
          "product_condition": "Opened, used 3 times per customer, Grade B"
        }
      },
      "task": "Process this cross-channel return: determine the correct refund amount, explain the process to the store associate, identify the fraud/leakage risk, and route the disposition.",
      "evaluation_criteria": [
        {
          "criterion": "correct_refund_amount",
          "weight": 0.35,
          "rubric": {
            "pass": "Refund at the actual purchase price ($499.99), NOT the store POS price ($699.99). The associate must look up the online order in the separate portal to verify the actual amount paid. Refund to original payment method — this prevents price-arbitrage via store credit. Explains to the associate: 'Always verify the actual purchase price for online returns; never use the store shelf price.'",
            "fail": "Refunds at the store price ($699.99) — a $200 overpayment. Alternatively, refunds at the regular online price ($649.99) — still a $150 overpayment. Does not verify the actual purchase price against the online order."
          }
        },
        {
          "criterion": "fraud_leakage_awareness",
          "weight": 0.30,
          "rubric": {
            "pass": "Identifies this as a cross-channel price arbitrage risk — one of the top 3 sources of return-related financial leakage. Explains that the process safeguard is: (1) always look up online order for actual purchase price, (2) refund to original payment method only (not store credit, not cash), (3) if order verification is impossible, process through online returns channel instead. Notes the systemic issue: the store's POS should integrate with the online OMS to auto-populate the correct price.",
            "fail": "Does not recognise the price arbitrage risk. Processes without verifying purchase price. Allows cash or store credit refund which bypasses the payment processor safeguard."
          }
        },
        {
          "criterion": "disposition",
          "weight": 0.20,
          "rubric": {
            "pass": "Grade B (opened, used 3 times). Route to open-box resale or certified refurbished channel at 65-75% of regular retail. For a Dyson V15, the open-box market is strong — recovery at $420-490 is realistic. Clean and repackage. Replace any hygiene-sensitive components (filter, brush roller) before resale.",
            "fail": "Restocks as new (it's been used). Does not consider hygiene components for a vacuum. Routes to liquidation when open-box recovery is significantly better."
          }
        },
        {
          "criterion": "process_improvement",
          "weight": 0.15,
          "rubric": {
            "pass": "Recommends system integration: the in-store POS should query the online OMS automatically when scanning a BORIS return so the associate doesn't need a manual lookup. Until that's built, a mandatory policy: all online-purchase returns processed in-store require online order verification before refund. Periodic audit of BORIS returns for price discrepancy patterns.",
            "fail": "Does not identify the systemic gap or recommend any process improvement."
          }
        }
      ]
    },
    {
      "id": "RRL-008",
      "name": "Swap fraud detection — electronics serial number mismatch",
      "difficulty": "medium",
      "category": "fraud-detection",
      "context": {
        "situation": "A customer returns an Apple iPad Pro 12.9\" (M2, $1,099.00) purchased 18 days ago, claiming 'changed my mind.' The RMA was approved and the product was returned via prepaid shipping label. During inspection, the technician verifies the serial number on the returned iPad against the order record. The serial number on the returned device (DMXFF1234ABC) does not match the serial number on the original sales order (DMXGG5678XYZ). The returned device is a same-model iPad Pro 12.9\" M2, but with a cracked corner on the back housing (not visible when the screen is face-up) and a battery health of 81%. The customer has been with you for 18 months, has $3,100 in lifetime purchases, and a 22% return rate.",
        "available_data": {
          "customer_name": "David Park",
          "order_number": "ORD-2025-64201",
          "product": "Apple iPad Pro 12.9-inch (M2) - 256GB - Space Gray",
          "product_sku": "APL-IPADPRO-129-M2-256-SG",
          "purchase_price_usd": 1099.00,
          "serial_on_order": "DMXGG5678XYZ",
          "serial_on_returned_device": "DMXFF1234ABC",
          "device_condition": "Cracked corner on back housing, screen functional, battery health 81%",
          "purchase_date": "2025-05-02",
          "return_date": "2025-05-20",
          "return_reason": "Changed my mind",
          "customer_ltv_usd": 3100,
          "customer_return_rate_pct": 22,
          "customer_account_age_months": 18
        }
      },
      "task": "Determine how to handle this return given the serial number mismatch, what actions to take, who to notify, and how to communicate with the customer.",
      "evaluation_criteria": [
        {
          "criterion": "fraud_identification",
          "weight": 0.30,
          "rubric": {
